use tauri::{Emitter,Manager};
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::{fs,path::{Path,PathBuf},process::Command,sync::Mutex};
#[derive(Default)] struct AppState{config:Mutex<AgentConfig>}
#[derive(Clone,Serialize,Deserialize,Default)] struct AgentConfig{api_base:String,model:String,api_key:String}
#[derive(Serialize)]struct AgentStatus{ready:bool,platform:String,version:&'static str}
fn config_path(app:&tauri::AppHandle)->Result<PathBuf,String>{app.path().app_config_dir().map(|p|p.join("config.json")).map_err(|e|e.to_string())}
fn load_config(app:&tauri::AppHandle)->AgentConfig{config_path(app).ok().and_then(|p|fs::read_to_string(p).ok()).and_then(|s|serde_json::from_str(&s).ok()).unwrap_or_default()}
#[tauri::command]fn status()->AgentStatus{AgentStatus{ready:true,platform:std::env::consts::OS.to_string(),version:"0.1.0"}}
#[tauri::command]fn get_config(app:tauri::AppHandle,state:tauri::State<AppState>)->Result<AgentConfig,String>{let mut c=state.config.lock().map_err(|e|e.to_string())?;if c.api_key.is_empty(){*c=load_config(&app)}Ok(c.clone())}
#[tauri::command]fn save_config(app:tauri::AppHandle,state:tauri::State<AppState>,config:AgentConfig)->Result<(),String>{let p=config_path(&app)?;fs::create_dir_all(p.parent().ok_or("invalid config path")?).map_err(|e|e.to_string())?;fs::write(p,serde_json::to_vec_pretty(&config).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;*state.config.lock().map_err(|e|e.to_string())?=config;Ok(())}
#[tauri::command]fn choose_project(app:tauri::AppHandle)->Option<String>{use tauri_plugin_dialog::DialogExt;app.dialog().file().blocking_pick_folder().map(|p|p.to_string())}
fn within(root:&Path,rel:&str)->Result<PathBuf,String>{let p=root.join(rel);let c=if p.exists(){p.canonicalize().map_err(|e|e.to_string())?}else{let parent=p.parent().unwrap_or(root);let pc=parent.canonicalize().map_err(|e|e.to_string())?;pc.join(p.file_name().ok_or("invalid filename")?)};if !c.starts_with(root){return Err("Path escapes selected workspace".into())}Ok(c)}
fn tool_exec(name:&str,args:&Value,root:&Path,app:&tauri::AppHandle)->Result<String,String>{match name{
"list_files"=>{let dir=within(root,args["path"].as_str().unwrap_or(".")).map_err(|e|e)?;let mut out=String::new();for e in fs::read_dir(dir).map_err(|e|e.to_string())?{let e=e.map_err(|e|e.to_string())?;out.push_str(&format!("{}{}\n",if e.file_type().map_err(|e|e.to_string())?.is_dir(){"[DIR] "}else{"[FILE] "},e.file_name().to_string_lossy()))}Ok(out)},
"read_file"=>{let p=within(root,args["path"].as_str().ok_or("missing path")?)?;fs::read_to_string(p).map_err(|e|e.to_string())},
"write_file"=>{let p=within(root,args["path"].as_str().ok_or("missing path")?)?;if let Some(parent)=p.parent(){fs::create_dir_all(parent).map_err(|e|e.to_string())?}fs::write(p,args["content"].as_str().unwrap_or("")).map_err(|e|e.to_string())?;Ok("File written.".into())},
"git_diff"=>{let o=Command::new("git").args(["diff","--"]).current_dir(root).output().map_err(|e|e.to_string())?;Ok(String::from_utf8_lossy(&o.stdout).to_string())},
"run_command"=>{let cmd=args["command"].as_str().ok_or("missing command")?;use tauri_plugin_dialog::DialogExt;if !app.dialog().message(format!("Forge wants to run this command in the selected workspace:\n\n{cmd}\n\nApprove command execution?")).buttons(tauri_plugin_dialog::MessageDialogButtons::OkCancel).blocking_show(){return Ok("Command denied by user.".into())}let mut c=if cfg!(windows){let mut c=Command::new("cmd");c.args(["/C",cmd]);c}else{let mut c=Command::new("sh");c.args(["-c",cmd]);c};let o=c.current_dir(root).output().map_err(|e|e.to_string())?;Ok(format!("Exit: {}\n{}\n{}",o.status,String::from_utf8_lossy(&o.stdout),String::from_utf8_lossy(&o.stderr)))} ,_=>Err(format!("Unknown tool: {name}"))}}
#[tauri::command]fn show_git_diff(project_path:String)->Result<String,String>{let root=PathBuf::from(project_path).canonicalize().map_err(|e|e.to_string())?;let o=Command::new("git").args(["diff","--"]).current_dir(root).output().map_err(|e|e.to_string())?;Ok(String::from_utf8_lossy(&o.stdout).to_string())}
#[tauri::command]async fn run_task(app:tauri::AppHandle,prompt:String,project_path:Option<String>,state:tauri::State<'_,AppState>)->Result<String,String>{
 let root=PathBuf::from(project_path.ok_or("Select a workspace first")?).canonicalize().map_err(|e|e.to_string())?;
 let cfg={let mut c=state.config.lock().map_err(|e|e.to_string())?;if c.api_key.is_empty(){*c=load_config(&app)}c.clone()};if cfg.api_key.is_empty()||cfg.model.is_empty(){return Err("Configure API key and model in Settings first.".into())}
 let client=reqwest::Client::new();let base=if cfg.api_base.is_empty(){"https://api.openai.com/v1".to_string()}else{cfg.api_base.trim_end_matches('/').to_string()};
 let tools=json!([{"type":"function","function":{"name":"list_files","description":"List workspace directory contents","parameters":{"type":"object","properties":{"path":{"type":"string"}},"required":["path"]}}},{"type":"function","function":{"name":"read_file","description":"Read a text file in workspace","parameters":{"type":"object","properties":{"path":{"type":"string"}},"required":["path"]}}},{"type":"function","function":{"name":"write_file","description":"Create or replace a workspace file","parameters":{"type":"object","properties":{"path":{"type":"string"},"content":{"type":"string"}},"required":["path","content"]}}},{"type":"function","function":{"name":"git_diff","description":"Show current Git working-tree diff","parameters":{"type":"object","properties":{} }}} ,{"type":"function","function":{"name":"run_command","description":"Execute a shell command in workspace (requires user approval)","parameters":{"type":"object","properties":{"command":{"type":"string"}},"required":["command"]}}}]);
 let mut msgs=vec![json!({"role":"system","content":format!("You are Forge Agent, an autonomous coding assistant. Work only inside this workspace: {}. Inspect before editing, explain actions briefly, use tools as needed, and finish with a concise summary.",root.display())}),json!({"role":"user","content":prompt})];
 for step in 0..12 {let _=app.emit("agent-progress",format!("Thinking / tool cycle {}",step+1));let resp=client.post(format!("{base}/chat/completions")).bearer_auth(&cfg.api_key).json(&json!({"model":cfg.model,"messages":msgs,"tools":tools,"tool_choice":"auto"})).send().await.map_err(|e|e.to_string())?;let body:Value=resp.json().await.map_err(|e|e.to_string())?;if body["error"].is_object(){return Err(body["error"]["message"].as_str().unwrap_or("API error").to_string())}let msg=body["choices"][0]["message"].clone();if msg.is_null(){return Err("Unexpected API response".into())}msgs.push(msg.clone());if let Some(calls)=msg["tool_calls"].as_array(){for call in calls{let name=call["function"]["name"].as_str().unwrap_or("");let args:Value=serde_json::from_str(call["function"]["arguments"].as_str().unwrap_or("{}")).unwrap_or(json!({}));let _=app.emit("agent-progress",format!("Tool: {name}"));let result=tool_exec(name,&args,&root,&app).unwrap_or_else(|e|format!("Tool error: {e}"));msgs.push(json!({"role":"tool","tool_call_id":call["id"],"content":result}));}continue}return Ok(msg["content"].as_str().unwrap_or("Task finished.").to_string())}
 Ok("Agent reached the tool-call limit. Review workspace changes.".into())
}
#[cfg_attr(mobile,tauri::mobile_entry_point)]pub fn run(){tauri::Builder::default().plugin(tauri_plugin_dialog::init()).manage(AppState::default()).invoke_handler(tauri::generate_handler![status,get_config,save_config,choose_project,show_git_diff,run_task]).run(tauri::generate_context!()).expect("error running Forge Agent");}
